String square(String key) {
  final visited = <String>{};
  final result = StringBuffer();
  final source = key;
  final alphabet = source.toUpperCase().replaceAll('J', 'I') + 'ABCDEFGHIKLMNOPQRSTUVWXYZ';
  for (var i = 0; i < alphabet.length; i++) {
    final char = alphabet[i];
    if (visited.add(char)) result.write(char);
  }
  return result.toString();
}

bool validPlayfair(String text) {
  final normalized = text.replaceAll('J', 'I');
  if (normalized.length.isOdd) return false;
  for (var i = 0; i < normalized.length; i += 2) {
    if (normalized[i] == normalized[i + 1]) return false;
  }
  return true;
}

String preparePlayfair(String text) {
  final normalized = text.replaceAll('J', 'I');
  final result = StringBuffer();
  var index = 0;
  while (index < normalized.length) {
    final first = normalized[index];
    final String second;
    if (index + 1 < normalized.length && normalized[index + 1] != first) {
      second = normalized[index + 1];
      index += 2;
    } else {
      second = first == 'X' ? 'Q' : 'X';
      index++;
    }
    result.write(first);
    result.write(second);
  }
  return result.toString();
}

String playfair(String text, String key, bool encrypt) {
  final board = square(key);
  final input = encrypt ? preparePlayfair(text) : text.replaceAll('J', 'I');
  final distance = encrypt ? 1 : 4;
  final result = StringBuffer();
  for (var i = 0; i < input.length; i += 2) {
    final a = board.indexOf(input[i]);
    final b = board.indexOf(input[i + 1]);
    var ra = a ~/ 5;
    var rb = b ~/ 5;
    var ca = a % 5;
    var cb = b % 5;
    if (ra == rb) {
      ca = (ca + distance) % 5;
      cb = (cb + distance) % 5;
    } else if (ca == cb) {
      ra = (ra + distance) % 5;
      rb = (rb + distance) % 5;
    } else {
      final temp = ca;
      ca = cb;
      cb = temp;
    }
    result.write(board[5 * ra + ca]);
    result.write(board[5 * rb + cb]);
  }
  return result.toString();
}

import 'dart:io';

bool isLetter(String char) {
  final c = char.codeUnitAt(0);
  return c >= 65 && c <= 90 || c >= 97 && c <= 122;
}

int letterValue(String char) {
  final c = char.codeUnitAt(0);
  return c >= 97 ? c - 97 : c - 65;
}

String upperLetter(int value) => String.fromCharCode(65 + value);

String letterString(String text) {
  final result = StringBuffer();
  for (var i = 0; i < text.length; i++) {
    final c = text[i];
    if (isLetter(c)) result.write(upperLetter(letterValue(c)));
  }
  return result.toString();
}

List<String> groups(String text) {
  final parts = <String>[];
  for (var i = 0; i < text.length; i += 5) {
    parts.add(text.substring(i, i + 5 > text.length ? text.length : i + 5));
  }
  final lines = <String>[];
  for (var i = 0; i < parts.length; i += 10) {
    lines.add(parts.skip(i).take(10).join(' '));
  }
  return lines;
}

int monogram(String text, List<int> weights) {
  var sum = 0;
  for (final c in text.codeUnits) sum += weights[c - 65];
  return sum;
}

int bigram(String text, List<List<int>> weights) {
  var sum = 0;
  for (var i = 1; i < text.length; i++) {
    sum += weights[text.codeUnitAt(i - 1) - 65][text.codeUnitAt(i) - 65];
  }
  return sum;
}

(List<int>, List<List<int>>) readWeights(String path) {
  final lines = File(path).readAsLinesSync();
  final mono = lines[1].split(' ').map(int.parse).toList();
  final bi = List.generate(26, (row) =>
      lines[row + 3].split(' ').map(int.parse).toList());
  return (mono, bi);
}

import 'scoring.dart';

int modulo(int number, [int modulus = 26]) =>
    (number % modulus + modulus) % modulus;

int inverse(int a) {
  for (var i = 1; i < 26; i++) {
    if (a * i % 26 == 1) return i;
  }
  throw StateError('Noninvertible affine key');
}

String applySubstitution(String text, String cipher, String key, bool encrypt) {
  var a = 1;
  var b = 0;
  if (cipher == 'caesar') b = int.parse(key);
  if (cipher == 'affine') {
    final pair = key.split(',');
    a = int.parse(pair[0]);
    b = int.parse(pair[1]);
  }
  final inv = cipher == 'affine' ? inverse(a) : 1;
  final plaintext = <int>[];
  final output = StringBuffer();
  var letterIndex = 0;
  for (var i = 0; i < text.length; i++) {
    final char = text[i];
    if (!isLetter(char)) {
      output.write(char);
      continue;
    }
    final x = letterValue(char);
    var shift = 0;
    if (cipher == 'vigenere') {
      shift = letterValue(key[letterIndex % key.length]);
    } else if (cipher == 'autokey') {
      shift = letterIndex < key.length ? letterValue(key[letterIndex])
          : plaintext[letterIndex - key.length];
    }
    final y = switch (cipher) {
      'caesar' => modulo(x + (encrypt ? b : -b)),
      'affine' => encrypt ? modulo(a * x + b) : modulo(inv * (x - b)),
      'vigenere' || 'autokey' => modulo(x + (encrypt ? shift : -shift)),
      _ => throw StateError('Unknown substitution cipher'),
    };
    plaintext.add(encrypt ? x : y);
    final base = char.codeUnitAt(0) >= 97 ? 97 : 65;
    output.writeCharCode(base + y);
    letterIndex++;
  }
  return output.toString();
}

import 'dart:math';

int railNumber(int position, int rails) {
  final cycle = 2 * rails - 2;
  final offset = position % cycle;
  return min(offset, cycle - offset);
}

String railFence(String text, int rails, bool encrypt) {
  final order = List.generate(text.length, (i) => i);
  order.sort((a, b) {
    final result = railNumber(a, rails).compareTo(railNumber(b, rails));
    return result != 0 ? result : a.compareTo(b);
  });
  final output = List.filled(text.length, '');
  for (var i = 0; i < order.length; i++) {
    if (encrypt) {
      output[i] = text[order[i]];
    } else {
      output[order[i]] = text[i];
    }
  }
  return output.join();
}

List<int> columnOrder(String key) {
  final order = List.generate(key.length, (i) => i);
  order.sort((a, b) {
    final result = key[a].compareTo(key[b]);
    return result != 0 ? result : a.compareTo(b);
  });
  return order;
}

String rankString(String key) {
  final rank = List.filled(key.length, '');
  final order = columnOrder(key);
  for (var i = 0; i < order.length; i++) {
    rank[order[i]] = String.fromCharCode(49 + i);
  }
  return rank.join();
}

String columnar(String text, String key, bool encrypt) {
  final output = List.filled(text.length, '');
  var pointer = 0;
  for (final column in columnOrder(key)) {
    for (var index = column; index < text.length; index += key.length) {
      if (encrypt) {
        output[pointer++] = text[index];
      } else {
        output[index] = text[pointer++];
      }
    }
  }
  return output.join();
}
